package java_basics;

public class Monthly_salary {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		double montsal=20000;
		double annsal;
		double sixmont;
		
		sixmont=6*montsal;
		annsal=12*montsal;
		
		System.out.println("Monthly salary    ="+montsal);
		System.out.println("Six months salary ="+sixmont);
		System.out.println("Annual salary     ="+annsal);
		

	}

}
